get_shipping_settings.code:
import com.webcommander.sdk.client.ApiResponse;
import java.util.Map;

ApiResponse response = client.shippingSettings().getShippingSettings();
Map<?, ?> settings = (Map<?, ?>) ((Map<?, ?>) response.getMap()).get("shipping_settings");
Map<?, ?> shippingProfile = (Map<?, ?>) settings.get("default_shipping_profile");
System.out.println(shippingProfile == null ? "No Shipping" : shippingProfile.get("id") + " " + shippingProfile.get("name"));
System.out.println(settings.get("enable_shipping_default_tax") + " " + settings.get("enable_delivery_default_tax"));
System.out.println(settings.get("enable_shipping_class") + " " + settings.get("enable_flat_view_class"));

