import com.webcommander.sdk.client.ApiResponse;
import java.util.Map;

ApiResponse response = client.shippingSettings().patchShippingSettings(
        Map.of("shipping_settings", Map.of("enable_shipping_default_tax", true)));
Map<?, ?> settings = (Map<?, ?>) ((Map<?, ?>) response.getMap()).get("shipping_settings");
System.out.println(settings.get("enable_shipping_default_tax"));
